/// <summary>
///    AVA <c>displayAVACompanyLogo</c> method.
/// </summary>
/// <returns>
///    <c>BitMap</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display BitMap displayAVACompanyLogo()
{
    BitMap          retVal;

    CompanyInfo     locCompanyInfo;
    CompanyImage    locCompanyImage;

    locCompanyInfo  = CompanyInfo::find();
    locCompanyImage = CompanyImage::findByRecord(locCompanyInfo);
    retVal          = locCompanyImage.Image;

    return retVal;
}

/// <summary>
///    AVA <c>displayAVACompanyAddressSingleLine</c> method.
/// </summary>
/// <returns>
///    <c>Addressing</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Addressing displayAVACompanyAddressSingleLine()
{
    Addressing  retVal;

    CompanyInfo locCompanyInfo;

    locCompanyInfo = CompanyInfo::find();

    retVal = AVAHelperClass::adress2singleLineFormat(locCompanyInfo.name(), locCompanyInfo.invoiceAddress().Address);

    return retVal;
}

