[SysClientCacheDataMethodAttribute(true)]
display Phone displayAVAFromContactPersonPhone()
{
    Phone retVal;   //@SYS7869

    if(this.FromContactPerson)
    {
        retVal = this.avaFromContactPersonDirPerson().availablePhone();
        if(!retVal)
        {
            retVal = this.avaFromContactPerson().phone();
        }
    }

    return retVal;
}

