/// <summary>
///    AVA <c>displayAVAFromAddress</c> method.
/// </summary>
/// <returns>
///    <c>LogisticsAddressing</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display LogisticsAddressing displayAVAFromAddress()
{
    LogisticsAddressing retVal;

    HcmWorkerName       locHcmWorkerName;
    LogisticsAddressing locLogisticsAddressing;

    if(this.FromPostalAddress)
    {
        locLogisticsAddressing  = this.FromAddress();
    }

    if(this.FromContactPerson)
    {
        locHcmWorkerName        = this.avaFromContactPerson().name();
    }

    retVal += this.FromAddressName;

    if(retVal && locHcmWorkerName)
    {
        retVal += '\n';
    }
    retVal += locHcmWorkerName;

    if(retVal && locLogisticsAddressing)
    {
        retVal += '\n';
    }
    retVal += locLogisticsAddressing;

    return retVal;
}

/// <summary>
///    AVA <c>displayAVAToAddress</c> method.
/// </summary>
/// <returns>
///    <c>LogisticsAddressing</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display LogisticsAddressing displayAVAToAddress()
{
    LogisticsAddressing retVal;   //@NDX:NDXDlvAddress

    HcmWorkerName       locHcmWorkerName;
    LogisticsAddressing locLogisticsAddressing;

    if(this.ToPostalAddress)
    {
        locLogisticsAddressing  = this.toAddress();
    }

    if(this.ToContactPerson)
    {
        locHcmWorkerName        = this.avaToContactPerson().name();
    }

    retVal += this.ToAddressName;

    if(retVal && locHcmWorkerName)
    {
        retVal += '\n';
    }
    retVal += locHcmWorkerName;

    if(retVal && locLogisticsAddressing)
    {
        retVal += '\n';
    }
    retVal += locLogisticsAddressing;

    return retVal;
}
